"""Interactive product landing page. Every record is synthetic demo content."""
def landing_home(lang, c, link):
    def t(zh, en): return zh if lang == 'zh' else en
    def photo(name, cls='', eager=False):
        return f'<picture class="{cls}"><source media="(max-width:760px)" srcset="assets/{name}-small.png"><img src="assets/{name}.png" width="1280" height="720" alt="" loading="{"eager" if eager else "lazy"}"></picture>'
    hero = f'''
<section class="landing-opening" aria-labelledby="landing-title">
 <div class="black-stage">
  <div class="hero-phone" aria-hidden="true">
   <div class="phone-speaker"></div><div class="phone-top">09:10 <span>迹库</span></div>
   <div class="phone-date">22 <small>OCTOBER</small></div>
   <div class="phone-source"><span class="source-dot"></span><small>{t('留下一刻','Keep a moment')}</small><strong class="capture-label" data-idle="{t('准备好了','Ready when you are')}" data-recording="{t('正在留下…','Capturing…')}" data-saved="{t('原音已保存','Original audio saved')}">{t('准备好了','Ready when you are')}</strong><div class="signal-lines">{''.join('<i></i>' for _ in range(21))}</div><p class="phone-time">00:42</p></div>
   <div class="phone-bottom"><span>◉</span><span>▤</span><span>⌕</span></div>
  </div>
  {photo('tap-scene-v4','hero-touch',True)}
  <div class="stage-message"><img class="stage-logo" src="assets/brand-mark.png" width="68" height="68" alt=""><p class="stage-brand">{t('迹库','Tracebook')}</p><h1 id="landing-title">{t('片刻留下，<br>线索接上。','Keep the moment.<br>Continue the thread.')}</h1><p>{t('你的个人资料与记忆库','Your personal library, with memory.')}</p><a class="play-demo" href="#capture-demo" aria-label="{t('进入记录互动演示','Go to the interactive capture demo')}"><span class="play-symbol" aria-hidden="true">••</span><span class="play-label">{t('体验敲两下','Try two taps')}</span></a></div>
  <p class="stage-caption">{t('AI 场景 · 界面演示，非运行截图','AI scene · Interface demo, not an app screenshot')}</p>
  <p class="capture-feedback" role="status" aria-live="polite" data-capture-feedback data-recording="{t('演示：正在留下声音，不使用你的麦克风。','Demo: capturing sound. Your microphone is not used.')}" data-saved="{t('演示：原音来源已留存。没有生成转写。可再次体验。','Demo: an original audio source is saved. No transcript was generated. Try again anytime.')}"></p>
 </div>
 <div class="opening-action"><a href="start.html" class="start-pill">{t('开始使用','Get started')} <span aria-hidden="true">↗</span></a><p>{t('开源开发版 · 暂无安装包','Open-source development build · No installer yet')}</p></div>
 <a href="#capture-ways" class="keep-exploring">{t('往下，接上这一天','Continue into your day')} <span aria-hidden="true">↓</span></a>
</section>'''
    panels = [
      ('phone', t('念头经过，不必停下来。','A passing thought. No need to stop.'),t('敲两下，<br><em>先留下。</em>','Tap twice.<br><em>Keep the thought.</em>'),t('手机背面的一个小动作，接上你已绑定的录音快捷指令。','A small gesture on your phone connects to the recording shortcut you have configured.'),photo('tap-scene-v4','hardware-photo'),t('轻点背面','Back Tap'),t('需在系统设置绑定快捷指令，解锁前台与麦克风授权。再运行一次可停止并保存；部分入口仍待真机验收。','Requires system shortcut binding, unlocked foreground access and microphone permission. Run again to stop and save; some entry paths still need real-device validation.')),
      ('watch', t('双手忙着，思绪仍可留下。','Hands busy. A thought worth keeping.'),t('手机收起，<br><em>抬腕留下。</em>','Phone away.<br><em>Keep it on your wrist.</em>'),t('让手表成为另一个记录入口。散步途中，不必掏出手机。','Make your watch another capture point. Keep a thought while your phone stays put.'),photo('walk-scene-v3','hardware-photo watch-photo'),t('腕上入口','On your wrist'),t('手表录音是独立入口。辅助触控捏合需系统另行绑定，不等于手机轻点背面；部分动作仍待真机验收。语音转写已接入，真实服务质量未验收。','Watch capture is a separate entry point. AssistiveTouch pinch requires separate system binding; it is not phone Back Tap. Some gestures still need device validation. Speech transcription is integrated; real-service quality is not validated.')),
      ('import',t('想法不只存在于声音里。','Not every thought begins as sound.'),t('已经写下的，<br><em>也接进来。</em>','Already written?<br><em>Bring it along.</em>'),t('文字、笔记和已适配的工具会话，带着自己的来源进入资料库。','Text, notes and adapted tool sessions enter your library with their own sources.'),f'<div class="import-object" aria-label="{t("合成导入资料示意","Synthetic import illustration")}"><div class="file-sheet sheet-back"><small>SESSION</small><strong>Codex / Claude Code</strong><span>16:20 · input</span></div><div class="file-sheet sheet-middle"><small>TEXT</small><strong>{t("秋季产品演示.md","Autumn demo.md")}</strong><span>document · v1</span></div><div class="file-sheet sheet-front"><img src="assets/brand-mark.png" alt="" width="42" height="42"><small>{t("资料库","LIBRARY")}</small><strong>{t("留下来源。<br>稍后接上。","Keep the source.<br>Pick it up later.")}</strong><p>{t("先预览，再确认导入","Preview. Then confirm the import.")}</p><div class="file-lines"><i></i><i></i><i></i></div></div></div>',t('已有资料','Existing material'),t('支持已适配格式，不代表任意文档。文字文件不包含 PDF 或 Office。聊天导入归笔记；未知时间明确标记。导入不自动发送给模型。','Only adapted formats are supported, not arbitrary documents. Text imports do not include PDF or Office. Chat imports become notes; unknown timestamps are marked. Import does not automatically send content to a model.'))]
    hardware = '<section id="capture-ways" class="pin-section" data-pinned-story><div class="pin-stage"><p class="hardware-label">'+t('迹库','Tracebook')+' <span>+</span> '+t('你选择的入口','Your chosen entry points')+'</p>'
    for index,(key,eyebrow,title,desc,art,tab,limit) in enumerate(panels):
        hardware += f'<article id="capture-{key}" class="hardware-panel {"is-active" if index==0 else ""}" data-story-step="{index}"><div class="hardware-copy"><p class="hardware-eyebrow">{eyebrow}</p><h2>{title}</h2><p class="hardware-description">{desc}</p><details class="hardware-limits"><summary>{t("设置与限制","Setup and limits")}</summary><p>{limit}</p></details></div><div class="hardware-object">{art}<span class="object-caption">{t("合成场景 / 流程示意","Synthetic scene / workflow illustration")}</span></div></article>'
    hardware += '<nav class="hardware-tabs" aria-label="'+t('选择记录入口','Choose a capture entry')+'">'+''.join(f'<a href="#capture-{panel[0]}" data-story-tab="{i}"><small>0{i+1}</small>{panel[5]}</a>' for i,panel in enumerate(panels))+'</nav><a href="#day-scenes" class="next-chapter">'+t('走进这一天','Into your day')+' ↘</a></div></section>'
    return hero + hardware + day_scenes(lang, photo) + capture_demo(lang, photo) + day_panels(lang, photo) + cli_scene(lang) + source_wall(lang) + landing_end(lang, link)

def day_scenes(lang, photo):
    def t(a,b): return a if lang=='zh' else b
    scenes=[('09:10','walk-scene-v3',t('走路想到','A thought on a walk'),t('别让一个好念头，<br>停在路上。','A good thought<br>need not stay behind.'),t('先留下声音，回来再接着想。','Keep the sound now. Continue the thought later.'),t('原音来源 · 00:42','Original audio · 00:42')),
            ('16:20','desk-scene-v3',t('桌前继续','Back at your desk'),t('回到桌前，<br>也回到刚才。','Back at your desk.<br>Back to the thought.'),t('把已有文字和工具会话，接到同一段思考里。','Bring existing text and tool sessions into the same thread.'),t('文字笔记 · 产品演示','Text note · Product demo')),
            ('07:30','morning-scene-v5',t('次日回看','The following morning'),t('给昨天，<br>一个新的开头。','Give yesterday<br>a new beginning.'),t('节点运行时，按设定时间回顾此前一天。','While your node runs, revisit the previous day on schedule.'),t('10/22 → 回看 10/21','22 OCT → Review 21 OCT'))]
    out='<section id="day-scenes" class="day-carousel" data-scene-carousel aria-label="'+t('一天中的三个场景','Three moments in a day')+'">'
    for i,(time,name,label,title,desc,result) in enumerate(scenes):
        out+=f'<article class="day-slide" data-scene="{i}" id="day-scene-{i}">{photo(name,"scene-background")}<div class="scene-shade"></div><span class="scene-clock">{time}</span><div class="scene-copy"><p>{label}</p><h2>{title}</h2><div>{desc}</div><span class="scene-result">{result}</span></div></article>'
    out+='<div class="scene-controls" hidden><div class="scene-tabs">'+''.join(f'<button type="button" data-scene-select="{i}" aria-controls="day-scene-{i}" aria-pressed="{"true" if i==0 else "false"}"><span>0{i+1}</span>{scene[2]}</button>' for i,scene in enumerate(scenes))+'</div><button type="button" class="scene-pause" data-scene-pause data-play="'+t('播放场景','Play scenes')+'" data-pause="'+t('暂停轮播','Pause scenes')+'">'+t('暂停轮播','Pause scenes')+'</button></div><p class="scene-provenance">'+t('AI 合成场景 · 固定示例资料','AI-generated scenes · Fixed synthetic examples')+'</p></section>'
    return out

def capture_demo(lang, photo):
    def t(a,b): return a if lang=='zh' else b
    return f'''<section id="capture-demo" class="capture-theatre" data-capture="idle"><div class="theatre-heading"><p>{t('一个动作，一条来源。','One gesture. One source.')}</p><h2>{t('敲两下。<br>让此刻留下来。','Tap twice.<br>Keep this moment.')}</h2><p>{t('试试这个动作。演示不使用麦克风，也不保存你的资料。','Try the gesture. This demo never uses your microphone or saves your material.')}</p></div><div class="capture-stage">{photo('tap-scene-v4','capture-photograph')}<div class="gesture-rings" aria-hidden="true"><i></i><i></i></div><div class="capture-phone"><div class="phone-speaker"></div><small>09:10 · {t('网页演示','WEB DEMO')}</small><img src="assets/brand-mark.png" width="44" height="44" alt=""><p class="capture-label" data-idle="{t('留下一段声音','Keep a little sound')}" data-recording="{t('演示录音中','Demo capture in progress')}" data-saved="{t('原音已留存','Original audio retained')}">{t('留下一段声音','Keep a little sound')}</p><div class="signal-lines" aria-hidden="true">{''.join('<i></i>' for _ in range(31))}</div><div class="capture-counter" data-counter>00:00</div><div class="capture-source" aria-hidden="true"><span>09:10</span><strong>{t('散步时的一个念头','A thought from a walk')}</strong><small>{t('原音 · 没有自动转写','Original audio · No automatic transcript')}</small></div><button type="button" class="capture-trigger" data-capture-demo data-start="{t('体验敲两下','Try two taps')}" data-stop="{t('停止并留存（演示）','Stop and save (demo)')}" data-again="{t('再体验一次','Try again')}" hidden>{t('体验敲两下','Try two taps')}</button></div></div><p class="capture-feedback" role="status" aria-live="polite" data-capture-feedback data-recording="{t('已触发网页演示。再次点击停止并显示合成原音来源。','Web demo started. Click again to stop and reveal the synthetic audio source.')}" data-saved="{t('合成原音来源已显示，没有录音、上传或生成转写。','Synthetic audio source shown. No recording, upload or transcription occurred.')}"></p><p class="theatre-note">{t('手机轻点背面需系统绑定快捷指令、解锁前台和麦克风授权。语音转写已接入，真实服务质量未验收。','Phone Back Tap requires system shortcut binding, unlocked foreground access and microphone permission. Speech transcription is integrated; real-service quality is not validated.')}</p></section>'''

def day_panels(lang, photo):
    def t(a,b): return a if lang=='zh' else b
    audio=f'<div class="ui-date">21 <small>OCTOBER</small></div><h3>{t("记录","Recordings")}</h3><details class="ui-source" open><summary><span>09:10</span>{t("散步时的一个念头","A thought from a walk")}</summary><div class="signal-lines" aria-hidden="true">'+''.join('<i></i>' for _ in range(23))+f'</div><p>00:42 · {t("原音","Original audio")}</p><small>{t("尚未添加文字。原音本身仍是一条来源。","No text added yet. The audio itself remains a source.")}</small></details><details class="ui-detail"><summary>{t("查看来源信息","View source details")}</summary><p>recording · DEMO_AUDIO<br>09:10 · v1</p></details>'
    badge=f'<small class="linked-memory-state" data-memory-badge data-candidate="{t("关联记忆：待确认","Linked memory: pending")}" data-confirmed="{t("关联记忆：已确认","Linked memory: confirmed")}" data-inactive="{t("关联记忆：已停用","Linked memory: inactive")}">{t("关联记忆：待确认","Linked memory: pending")}</small>'
    daily=f'<div class="ui-clock">07:30</div><p class="ui-date-bridge">22 OCT <span>→</span> 21 OCT</p><h3>{t("昨天留下的","Yesterday, retained")}</h3><div class="daily-demo-list"><article><time>10:35</time><strong>{t("演示先给出原文。","Show the source first.")}</strong><small>note / NOTE_ID / v1</small>{badge}<a class="source-route" id="daily-note-source" href="#original-example" data-source-open>{t("追踪这条来源 →","Follow this source →")}</a></article><article><time>16:20</time><strong>{t("周四彩排，检查引用。","Thursday rehearsal: check citations.")}</strong><small>note · v1</small></article><article><time>20:10</time><strong>{t("原音等待添加文字。","Audio awaiting text.")}</strong><small>recording · v1</small></article></div><details class="ui-detail"><summary>{t("回顾范围","Review scope")}</summary><p>{t("笔记与录音资料。模型文字分析需另行配置并开启，不是定时录音。","Notes and recordings. Model text analysis needs separate configuration and activation. This is not scheduled recording.")}</p></details>'
    imports=f'<h3>{t("资料汇集","Your material")}</h3><p class="ui-subtitle">{t("秋季产品演示","Autumn product demo")}</p><div class="ui-filter" data-filter-controls hidden><button type="button" data-filter="all" aria-pressed="true">{t("全部","All")}</button><button type="button" data-filter="note" aria-pressed="false">note</button><button type="button" data-filter="input" aria-pressed="false">input</button><button type="button" data-filter="document" aria-pressed="false">document</button></div><p class="filter-status" data-filter-status data-label="{t("条合成来源","synthetic sources")}" role="status" aria-live="polite">4 {t("条合成来源","synthetic sources")}</p><div class="import-demo-list">'+''.join(f'<article data-source-kind="{kind}"><span>{kind}</span><strong>{name}</strong><small>{stamp} · v1</small></article>' for kind,name,stamp in [('note',t('演示思路','Demo notes'),'10:35'),('note',t('聊天导入笔记','Imported chat note'),'11:20'),('input','Codex / Claude Code','16:20'),('document',t('演示提纲.md','Outline.md'),t('文件修改时间','File modified time'))])+f'</div><small>{t("合成资料。可用时间与来源保留，未知时间明确标记。","Synthetic material. Available timestamps and sources retained; unknown times marked.")}</small>'
    memory=f'<p class="ui-status" id="memory-state" tabindex="-1" data-memory-status role="status" aria-live="polite" data-candidate="{t("手动候选","Manual candidate")}" data-confirmed="{t("本人确认 · v1","Confirmed by you · v1")}" data-inactive="{t("已停用 · 依据保留","Inactive · Evidence retained")}">{t("手动候选","Manual candidate")}</p><h3>{t("值得继续用的部分","Worth keeping")}</h3><blockquote>{t("秋季产品演示：先展示原文，再展示整理结果。","Autumn product demo: show the original before the organized result.")}</blockquote><details class="ui-detail" open><summary>{t("依据原文","Source evidence")}</summary><p>{t("“演示先给出原文，再展示整理结果。”","“Show the original before the organized result.”")}<small>note / NOTE_ID / v1</small></p></details><button type="button" class="ui-action" data-confirm-memory data-confirm="{t("确认这条（演示）","Confirm this (demo)")}" data-deactivate="{t("停用这条（演示）","Deactivate this (demo)")}" data-restore="{t("恢复这条（演示）","Restore this (demo)")}" data-state="candidate" hidden>{t("确认这条（演示）","Confirm this (demo)")}</button><a class="source-route" id="memory-source-link" href="#original-example" data-source-open>{t("回到这条原文","Back to this source")}</a><button type="button" class="demo-reset" data-memory-reset hidden>{t("重置记忆演示","Reset memory demo")}</button><p class="ui-footnote">{t("只改变网页演示，不写入客户端。自动模型记忆整理仍在开发。","Changes only this web demo, not your client. Automated model memory organization is still in development.")}</p>'
    files=f'<h3>{t("自己的文件","Your own files")}</h3><div class="file-browser"><p>▱ Tracebook</p><p>　├ notes</p><p>　├ recordings</p><p>　├ memories</p><p>　└ history</p></div><details class="ui-detail"><summary>{t("展开文字导出示意","Open text export example")}</summary><pre># {t("产品演示","Product demo")}\n\n{t("演示先给出原文，再展示整理结果。","Show the original before the organized result.")}\nsource: note / NOTE_ID\nversion: 1</pre></details><p class="ui-footnote">{t("文字可带走。原音与凭证不包含，不是完整备份或自动恢复包。","Take your text. Original audio and credentials are excluded; this is not a full backup or auto-restore package.")}</p>'
    data=[('walk-scene-v3',t('09:10 / 刚刚','09:10 / Just now'),t('刚才的想法，<br>还在。','That passing thought.<br>Still here.'),t('先保存原音，不急着把一切变成答案。','Keep the original sound. Not everything needs an instant answer.'),audio),('morning-scene-v5',t('次日 07:30 / 回看','NEXT DAY, 07:30 / Review'),t('到了明早，<br>再回看昨天。','Tomorrow morning.<br>A little room for yesterday.'),t('设好时间与时区。节点运行时，按来源汇集此前一天的笔记与录音资料。','Choose a time and timezone. While the node runs, gather the previous day’s notes and recordings with their sources.'),daily),('desk-scene-v3',t('16:20 / 接着做','16:20 / Continue'),t('散在各处，<br>也找得到。','More than one place.<br>One thread to return to.'),t('导入已有资料，保留各自的来处。不是把所有内容都交给模型。','Import existing material and keep its origins. This does not send everything to a model.'),imports),('review-scene-v5',t('后来 / 值得留下','LATER / Worth keeping'),t('值得留下的，<br>由你确认。','What stays?<br>You decide.'),t('从原文提出候选，由你确认。想法变了，还可以修订、停用与恢复。','Propose a candidate from the source. Confirm it yourself. Revise, deactivate or restore it when things change.'),memory),('coding-scene-v5',t('继续 / 文件归你','NEXT / Yours to keep'),t('记录不止能看，<br>也能继续用。','Not just something to see.<br>Something to keep using.'),t('保留来源与版本，文字可以带走。下一次工具调用，也有线索可循。','Keep sources and versions. Take your text. Give your next tool call a thread to follow.'),files)]
    out='<section class="days-story" id="days-story"><div class="chapter-band"><span>'+t('留下，然后接着走。','Keep it. Then keep going.')+'</span><p>'+t('同一段思考，经过不同的时刻。','One thought, across different moments.')+'</p></div>'
    for i,(name,label,title,desc,ui) in enumerate(data):
        ui_id=' id="memory-example" tabindex="-1"' if i==3 else ''
        out+=f'<article class="day-product {"reverse" if i%2 else ""}">{photo(name,"product-background")}<div class="product-shade"></div><div class="product-copy"><p>{label}</p><h2>{title}</h2><div>{desc}</div></div><div class="product-phone"><div class="phone-speaker"></div><div class="phone-ui"{ui_id}><div class="ui-brand"><img src="assets/brand-mark.png" alt="" width="20" height="20">{t("迹库","Tracebook")}<span>{t("演示","DEMO")}</span></div>{ui}</div></div><p class="product-provenance">{t("AI 场景 · 合成资料与界面演示，非运行截图","AI scene · Synthetic material and interface demo, not an app screenshot")}</p></article>'
    return out+'</section>'

def cli_scene(lang):
    def t(a,b):return a if lang=='zh' else b
    commands=['python3 integrations/lifto-library/scripts/lifto.py search "产品演示" --scope notes','python3 integrations/lifto-library/scripts/lifto.py query "产品演示" --scope notes','python3 integrations/lifto-library/scripts/lifto.py read note NOTE_ID']
    titles=[t('查找线索','Find the thread'),t('缩小范围','Narrow the scope'),t('回到原文','Read the original')]
    descriptions=[t('从已授权的资料里，找到与工作相关的来源。','Find relevant sources in the material you have authorized.'),t('查询返回检索结果，不生成模型回答。','Query returns retrieved results, not generated model answers.'),t('读取来源正文，带着依据继续工作。','Read the source text. Continue with the evidence in view.')]
    return f'''<section class="cli-experience" id="cli-experience"><div class="cli-story"><p class="eyebrow">CLI · {t('授权只读','SCOPED READ-ONLY')}</p><h2>{t('换一个工具，<br>思路不必重来。','A different tool.<br>The same thread.')}</h2><p>{t('查找、查询、读取。让工具回到你的原文，而不是重新猜你的背景。','Search, query, read. Let tools return to your sources instead of guessing your context again.')}</p><div class="cli-steps">{''.join(f'<button type="button" data-cli-step="{i}" aria-pressed="{"true" if i==0 else "false"}" aria-controls="cli-terminal" data-command="{commands[i].replace(chr(34),"&quot;")}" hidden><span>0{i+1}</span><strong>{titles[i]}</strong><p>{descriptions[i]}</p></button>' for i in range(3))}</div><noscript><p>{' → '.join(titles)}</p></noscript><details class="cli-limits"><summary>{t('授权与运行条件','Authorization and requirements')}</summary><p>{t('命令从仓库根目录执行，预先配置 LIFTO_URL 与独立只读凭证 LIFTO_TOKEN_FILE。仅 capabilities / search / query / read，不写文件、不批准记忆、不录音、不改设置。工具会话归档与只读检索是不同方向。','Run from the repository root after configuring LIFTO_URL and the separate scoped credential LIFTO_TOKEN_FILE. Only capabilities / search / query / read: no file writes, memory approvals, recording or settings changes. Session archiving and read-only retrieval are separate directions.')}</p></details></div><div class="cli-device"><div class="terminal-top"><span></span><span></span><span></span><small>{t('命令示例 · 非执行结果','Command example · Not executed')}</small></div><div id="cli-terminal"><p class="terminal-prompt">$ <code data-cli-command>{commands[0]}</code></p><div class="terminal-result"><small>{t('合成检索示意','SYNTHETIC RETRIEVAL')}</small><div data-cli-result="0"><p>01 · NOTE_ID · note · v1</p><blockquote>{t('秋季产品演示 · 10:35','Autumn product demo · 10:35')}</blockquote><p>02 · NOTE_02 · note · v1</p><blockquote>{t('周四彩排 · 16:20','Thursday rehearsal · 16:20')}</blockquote></div><div data-cli-result="1" hidden><p>NOTE_ID · {t('匹配片段','Matching passage')}</p><blockquote>{t('演示先给出原文，再展示整理结果。','Show the original before the organized result.')}</blockquote><p>{t('检索摘句，不是模型回答。','Retrieved passage, not a model answer.')}</p></div><div data-cli-result="2" hidden><p>note / NOTE_ID / v1</p><blockquote>{t('原文已在下方展开。','The original is expanded below.')}</blockquote><p>{t('标题、日期、内容版本与正文。','Title, date, content version and full text.')}</p></div><button type="button" class="citation-button" id="source-citation" data-citation aria-controls="original-example" hidden>[1] {t('查看原文','Read source')}</button><a class="citation-fallback" href="#original-example">[1] {t('原文','Source')}</a></div></div><div class="terminal-original" id="original-example" tabindex="-1"><div>{t('原文阅读','ORIGINAL SOURCE')} <span>NOTE_ID · v1</span></div><a href="#source-citation" class="citation-return" data-citation-return hidden>{t('返回入口','Back to entry')}</a><h3>{t('秋季产品演示','Autumn product demo')}</h3><p><span>01</span>{t('10月21日 10:35 · 文字笔记','21 OCT, 10:35 · Written note')}</p><p class="cited-line" data-cited-line><span>02</span><mark>{t('演示先给出原文，再展示整理结果。','Show the original before the organized result.')}</mark></p><p><span>03</span>{t('让观众先看见依据，再解释整理过程。','Let the audience see the evidence before explaining the organization.')}</p><small class="linked-memory-state" data-memory-badge data-candidate="{t('关联记忆：待确认','Linked memory: pending')}" data-confirmed="{t('关联记忆：已确认','Linked memory: confirmed')}" data-inactive="{t('关联记忆：已停用','Linked memory: inactive')}">{t('关联记忆：待确认','Linked memory: pending')}</small><a class="source-route" href="#memory-example" data-memory-open>{t('看看基于它的记忆 →','See the memory based on it →')}</a><small class="source-readonly">{t('CLI 只读，确认由你完成。','CLI is read-only. Confirmation stays with you.')}</small></div></div></section>'''

def landing_end(lang, link):
    def t(a,b):return a if lang=='zh' else b
    return f'''<section class="landing-close"><p>TRACEBOOK · OPEN SOURCE</p><h2>{t('把留下的信息，<br>整理成自己的记忆。','Keep your material.<br>Make it your memory.')}</h2><div class="actions">{link('',t('查看源码','View source'),'start-pill')}{link('/blob/main/docs/development.md',t('构建指南','Build guide'),'text-link')}</div><p>{t('三端源码公开 · MIT · 开发版，尚无已签名安装包','Three native clients · MIT · Development build. No signed installer.')}</p><div class="closing-columns"><div><span>01</span><h3>{t('源码公开，一起往前。','Open source. Built together.')}</h3><p>{t('电脑、手机与手表原生客户端。先从开发版能做的开始。','Native desktop, phone and watch clients. Start with what the development build can do.')}</p></div><div><span>02</span><h3>{t('资料归你，来源还在。','Your material. Sources intact.')}</h3><p>{t('选择自己的资料夹，保留原文与版本。文字可带走，不是完整备份。','Choose your own folder. Keep originals and versions. Text is portable, not a complete backup.')}</p></div><div><span>03</span><h3>{t('模型可选，边界清楚。','Optional models. Clear boundaries.')}</h3><p>{t('自行配置并启用服务，可能发送文字与产生费用。导入不等于发给模型。','Configure and enable your own provider. Processing may send text and incur fees. Import is not model processing.')}</p></div></div><div class="landing-faq"><details><summary>{t('现在能做什么？','What works today?')}</summary><p>{t('记录与导入、资料检索、原文阅读、四类来源手动记忆确认与修订已有。文字导入支持已适配格式，不支持 PDF / Office；工具会话支持已适配的 Codex 与 Claude Code 格式。','Capture, adapted imports, retrieval, original reading and manual memory confirmation/revision across four source types are available. Text imports do not include PDF or Office; adapted Codex and Claude Code sessions are supported.')}</p></details><details><summary>{t('模型与隐私怎么选择？','What about models and privacy?')}</summary><p>{t('导入不会自动发送给模型。文字分析需配置并启用，自备服务可能计费；真实模型质量尚未验收。本站互动只操作固定合成示例，不请求麦克风，不保存或上传个人资料。','Import does not automatically send material to a model. Text analysis needs configuration and activation; your provider may charge. Real-model quality is not yet validated. These interactions use fixed synthetic examples, never request a microphone, and do not retain or upload personal material.')}</p></details><details><summary>{t('还有哪些在开发？','What is still in development?')}</summary><p>{t('语音转写适配器与持久队列已实现，真实服务识别质量未验收，自动发送默认关闭。自动模型记忆整理仍在开发。资料对话不会生成模型回答。异地云同步与后台链路仍待真实验收。文字导出不含原音与凭证，不是完整备份或自动恢复包。','Speech transcription and its durable queue are implemented; real-service recognition quality is not validated and automatic sending is off by default. Automated model memory organization is still in development. Source conversation does not generate model answers. Remote cloud sync and background workflows still need real-world validation. Text export excludes original audio and credentials; it is not a full backup or auto-restore package.')}</p></details></div></section>'''

def source_wall(lang):
    def t(a,b):return a if lang=='zh' else b
    records=[('10:35','note',t('演示先给出原文，再展示整理结果。','Show the original before the organized result.')),
    ('16:20','note',t('周四彩排，先检查引用是否能打开。','For Thursday’s rehearsal, check that citations open.')),
    ('09:10','recording',t('散步时的一个念头。原音等待添加文字。','A thought from a walk. Audio awaiting text.')),
    ('16:20','input',t('工具会话留下上下文，下一次不从头猜。','A tool session leaves context for the next step.')),
    ('—','document',t('秋季产品演示提纲，保留来源与内容版本。','Autumn demo outline. Source and version retained.'))]
    out='<section class="source-reflections"><p>'+t('留下的，不必马上变成答案。','Not every trace needs an immediate answer.')+'</p><h2>'+t('每一次留下，<br>都有来处。','Every trace.<br>A source to return to.')+'</h2><div class="source-wall">'
    for column in range(5):
        out+='<div class="source-column">'
        for row in range(3):
            i=(column+row*2)%len(records);time,kind,quote=records[i]
            out+=f'<details class="source-slip"><summary><small>{time} / {kind}</small><span>{quote}</span><i aria-hidden="true">↗</i></summary><div>{t("合成示例","Synthetic example")} · {kind}<br>{t("来源与内容版本 v1","Source and content version v1")}</div></details>'
        out+='</div>'
    return out+'</div><p class="wall-caption">'+t('本页同一组合成资料 · 点开查看来源，不生成模型反思','The same synthetic material used throughout this page · Open a source, not a generated reflection')+'</p></section>'
